+import org.junit.Test;
+
+import java.io.File;
+import java.io.IOException;
+
+import static org.junit.Assert.assertTrue;
+
+public class ResourceDirectoryTraversalTest extends BaseTest {
+
+    @BeforeClass
+    public static void beforeClass() throws Exception {
+        TestUtils.cleanFrameworkFile();
+        sTmpDir = new ExtFile(OS.createTempDirectory());
+        TestUtils.copyResourceDir(ResourceDirectoryTraversalTest.class, "decode/arbitrary-write/", sTmpDir);
+        Assume.assumeFalse(OSDetection.isWindows());
+    }
+
+    @AfterClass
+    public static void afterClass() throws BrutException {
+        OS.rmdir(sTmpDir);
+    }
+
+    @Test
+    public void checkIfMaliciousRawFileIsDisassembledProperly() throws BrutException, IOException {
+        String apk = "GHSA-2hqv-2xv4-5h5w.apk";
+
+        Config config = Config.getDefaultConfig();
+        config.forceDelete = true;
+        ApkDecoder apkDecoder = new ApkDecoder(config, new File(sTmpDir + File.separator + apk));
+        File outDir = new File(sTmpDir + File.separator + apk + ".out");
+        apkDecoder.decode(outDir);
+
+        File pocTestFile =  new File(outDir,"res/raw/poc");
+        assertTrue(pocTestFile.exists());
+    }
+}"}, {"sha": "269b3fc07e21d0e284d69910f07b10bcb0479b62", "filename": "brut.apktool/apktool-lib/src/test/java/brut/androlib/util/UnknownDirectoryTraversalTest.java", "status": "modified", "additions": 6, "deletions": 6, "changes": 12, "blob_url": "https://github.com/iBotPeaches/Apktool/blob/d348c43b24a9de350ff6e5bd610545a10c1fc712/brut.apktool%2Fapktool-lib%2Fsrc%2Ftest%2Fjava%2Fbrut%2Fandrolib%2Futil%2FUnknownDirectoryTraversalTest.java", "raw_url": "https://github.com/iBotPeaches/Apktool/raw/d348c43b24a9de350ff6e5bd610545a10c1fc712/brut.apktool%2Fapktool-lib%2Fsrc%2Ftest%2Fjava%2Fbrut%2Fandrolib%2Futil%2FUnknownDirectoryTraversalTest.java", "contents_url": "https://api.github.com/repos/iBotPeaches/Apktool/contents/brut.apktool%2Fapktool-lib%2Fsrc%2Ftest%2Fjava%2Fbrut%2Fandrolib%2Futil%2FUnknownDirectoryTraversalTest.java?ref=d348c43b24a9de350ff6e5bd610545a10c1fc712", "patch": "@@ -51,7 +51,7 @@ public static void afterClass() throws BrutException {

